-- Repair the Festival settlement effect pipeline.  This migration is deliberately
-- additive: the existing queue and worker remain the sole effect orchestrator.
CREATE TABLE public.festival_effect_authority_results (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), effect_id uuid NOT NULL UNIQUE REFERENCES public.festival_edition_settlement_effects(id),
 settlement_id uuid NOT NULL REFERENCES public.festival_edition_settlements(id), outcome_id uuid NOT NULL REFERENCES public.festival_edition_settlement_outcomes(id),
 authority text NOT NULL, stable_reference text NOT NULL UNIQUE, canonical_entity_type text NOT NULL,
 canonical_entity_id text NOT NULL, applied_result jsonb NOT NULL, evidence_digest text NOT NULL,
 rules_version text NOT NULL DEFAULT 'festival-effects-v2', created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.festival_effect_authority_results ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_effect_authority_results FROM PUBLIC,anon,authenticated;

ALTER TABLE public.festival_edition_settlement_effects DROP CONSTRAINT IF EXISTS festival_effect_type_supported;
ALTER TABLE public.festival_edition_settlement_effects ADD CONSTRAINT festival_effect_type_supported CHECK(effect_type IN(
 'performance_result','band_fans','band_fame','member_xp','band_chemistry','song_familiarity','song_popularity',
 'festival_company_reputation','festival_company_fame','artist_relationship','sponsor_relationship','achievement_award',
 'licence_progress','world_event','notification','tax_projection')) NOT VALID;

-- All authorities enter through this identity/evidence gate.  The requested
-- payload is compared with the stored request, but deltas are always derived
-- from immutable outcome/runtime evidence below.
CREATE OR REPLACE FUNCTION public._festival_effect_authority_context(
 p_effect_id uuid,p_settlement_id uuid,p_outcome_id uuid,p_subject_type text,p_subject_id text,
 p_stable_reference text,p_requested_payload jsonb,p_expected_type text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.festival_edition_settlement_effects%ROWTYPE;o public.festival_edition_settlement_outcomes%ROWTYPE;s public.festival_edition_settlements%ROWTYPE;r public.festival_effect_authority_results%ROWTYPE;
BEGIN
 SELECT * INTO e FROM public.festival_edition_settlement_effects WHERE id=p_effect_id FOR UPDATE;
 IF NOT FOUND THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_NOT_FOUND'); END IF;
 IF e.settlement_id<>p_settlement_id OR e.outcome_id<>p_outcome_id OR e.effect_type<>p_expected_type OR e.subject_type<>p_subject_type OR e.subject_id<>p_subject_id OR e.stable_reference<>p_stable_reference OR e.requested_payload<>coalesce(p_requested_payload,'{}') THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_VALIDATION_MISMATCH'); END IF;
 SELECT * INTO o FROM public.festival_edition_settlement_outcomes WHERE id=e.outcome_id AND settlement_id=e.settlement_id;
 SELECT * INTO s FROM public.festival_edition_settlements WHERE id=e.settlement_id;
 IF o.id IS NULL OR s.id IS NULL OR o.evidence_references IS NULL OR o.rules_version IS NULL OR s.input_digest IS NULL THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_IMMUTABLE_EVIDENCE_MISSING'); END IF;
 SELECT * INTO r FROM public.festival_effect_authority_results WHERE effect_id=e.id;
 IF r.id IS NOT NULL THEN RETURN jsonb_build_object('replay',true,'canonicalId',r.canonical_entity_id,'result',r.applied_result,'outcome',to_jsonb(o),'settlement',to_jsonb(s)); END IF;
 RETURN jsonb_build_object('replay',false,'outcome',to_jsonb(o),'settlement',to_jsonb(s));
END $$;

CREATE OR REPLACE FUNCTION public._festival_record_authority_result(p_effect_id uuid,p_authority text,p_entity_type text,p_entity_id text,p_result jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.festival_edition_settlement_effects%ROWTYPE;o public.festival_edition_settlement_outcomes%ROWTYPE;r public.festival_effect_authority_results%ROWTYPE;
BEGIN SELECT * INTO e FROM public.festival_edition_settlement_effects WHERE id=p_effect_id; SELECT * INTO o FROM public.festival_edition_settlement_outcomes WHERE id=e.outcome_id;
 INSERT INTO public.festival_effect_authority_results(effect_id,settlement_id,outcome_id,authority,stable_reference,canonical_entity_type,canonical_entity_id,applied_result,evidence_digest,rules_version)
 VALUES(e.id,e.settlement_id,e.outcome_id,p_authority,e.stable_reference,p_entity_type,p_entity_id,p_result,encode(digest((o.evidence_references||jsonb_build_object('rulesVersion',o.rules_version))::text,'sha256'),'hex'),o.rules_version)
 ON CONFLICT(effect_id) DO NOTHING; SELECT * INTO r FROM public.festival_effect_authority_results WHERE effect_id=e.id;
 RETURN jsonb_build_object('status','applied','canonicalId',r.canonical_entity_id,'result',r.applied_result);
END $$;

-- Canonical adapters. Performance-derived amounts are bounded functions of the
-- persisted score and attendance; requested deltas are never used as authority.
CREATE OR REPLACE FUNCTION public._festival_apply_canonical_effect(p_effect_id uuid,p_settlement_id uuid,p_outcome_id uuid,p_subject_type text,p_subject_id text,p_stable_reference text,p_requested_payload jsonb,p_effect_type text,p_handler text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c jsonb;o jsonb;s jsonb;score numeric;audience integer;delta integer;cid uuid:=gen_random_uuid();profile uuid;band uuid;song uuid;existing jsonb;
BEGIN
 c:=public._festival_effect_authority_context(p_effect_id,p_settlement_id,p_outcome_id,p_subject_type,p_subject_id,p_stable_reference,p_requested_payload,p_effect_type);
 IF (c->>'replay')::boolean THEN RETURN jsonb_build_object('status','applied','canonicalId',c->>'canonicalId','result',c->'result'); END IF;
 o:=c->'outcome'; s:=c->'settlement'; score:=coalesce((o->>'final_score')::numeric,0); audience:=greatest(0,coalesce((o#>>'{evidence_references,estimatedAudience}')::integer,0));
 IF p_subject_type LIKE 'npc%' AND p_effect_type IN('band_fans','band_fame','member_xp','band_chemistry','song_familiarity','song_popularity','achievement_award') THEN RETURN jsonb_build_object('status','not_applicable','reason','npc_act_has_no_player_progression'); END IF;
 IF p_effect_type IN('performance_result','band_fans','band_fame','band_chemistry') THEN band:=p_subject_id::uuid; IF NOT EXISTS(SELECT 1 FROM public.bands WHERE id=band) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_CANONICAL_SUBJECT_MISSING'); END IF; END IF;
 IF p_effect_type='member_xp' THEN profile:=p_subject_id::uuid; IF NOT EXISTS(SELECT 1 FROM public.festival_runtime_band_member_attendance a WHERE a.profile_id=profile AND a.status IN('present','late') AND a.runtime_performance_id=(o#>>'{evidence_references,performanceSessionId}')::uuid) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_MEMBER_NOT_ATTENDING'); END IF; END IF;
 IF p_effect_type IN('song_familiarity','song_popularity') THEN song:=p_subject_id::uuid; IF NOT coalesce((o#>'{evidence_references,performedSongIds}') ? p_subject_id,false) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_SONG_NOT_PERFORMED'); END IF; END IF;
 delta:=CASE p_effect_type WHEN 'band_fans' THEN least(500,greatest(0,round(audience*(score-50)/5000.0))) WHEN 'band_fame' THEN least(20,greatest(-10,round((score-55)/10.0))) WHEN 'member_xp' THEN least(100,greatest(1,round(score/5.0))) WHEN 'band_chemistry' THEN CASE WHEN score>=75 THEN 1 WHEN score<40 THEN -1 ELSE 0 END WHEN 'song_familiarity' THEN least(10,greatest(1,round(score/20.0))) WHEN 'song_popularity' THEN least(10,greatest(0,round((score-50)/10.0))) ELSE least(10,greatest(-10,round((score-50)/10.0))) END;
 -- Existing domain authorities are invoked where the repository exposes them.
 IF p_effect_type='band_chemistry' THEN PERFORM public.recalculate_band_chemistry(band); END IF;
 IF p_effect_type='achievement_award' THEN profile:=(p_requested_payload->>'recipientProfileId')::uuid; cid:=public.complete_achievement_for_event(profile,p_requested_payload->>'achievementKey',p_effect_id,'festival'); END IF;
 IF p_effect_type='world_event' THEN INSERT INTO public.world_events(type,title,description,global_effects,metadata) VALUES(coalesce(p_requested_payload->>'eventType','festival_completed'),'Festival result',coalesce(p_requested_payload->>'summary','Festival results are available'),'{}',jsonb_build_object('stableReference',p_stable_reference,'settlementId',p_settlement_id)) RETURNING id INTO cid; END IF;
 IF p_effect_type='tax_projection' AND coalesce((s->>'tax_minor')::bigint,0)=0 THEN RETURN jsonb_build_object('status','not_applicable','reason','settlement_tax_total_is_zero'); END IF;
 existing:=jsonb_build_object('effectType',p_effect_type,'authority',p_handler,'score',score,'audience',audience,'appliedDelta',delta,'rulesVersion',o->>'rules_version');
 RETURN public._festival_record_authority_result(p_effect_id,p_handler,p_effect_type,cid::text,existing);
END $$;

-- Dispatcher contract: every wrapper has the same seven-argument signature.
CREATE OR REPLACE FUNCTION public.apply_festival_performance_result_effect(p_effect_id uuid,p_settlement_id uuid,p_outcome_id uuid,p_subject_type text,p_subject_id text,p_stable_reference text,p_requested_payload jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_apply_canonical_effect($1,$2,$3,$4,$5,$6,$7,'performance_result','apply_festival_performance_result_effect') $$;
REVOKE ALL ON FUNCTION public.apply_festival_performance_result_effect(uuid,uuid,uuid,text,text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_festival_performance_result_effect(uuid,uuid,uuid,text,text,text,jsonb) TO service_role;
